const FAILED_IMAGE_URL="https://cdn.bootstrapstudio.io/placeholders/1400x800.png";function randomUUID(){return Math.random().toString(36).substring(2,10)}const loginValidChecker=setInterval((()=>{const e=new URLSearchParams(window.location.search);fetch(`/api/check-login-validity/?auth=${e.get("auth")}`).then((e=>{if(200!==e.status)throw window.location.replace("/admin-login/"),new Error(`Failed validating login credentials! ${e.status}`)}))}),1e4);function showElementByID(e){document.getElementById(e).classList.remove("d-none")}function hideElementByID(e){document.getElementById(e).classList.add("d-none")}function updateEvents(){hideElementByID("update-events-button"),showElementByID("update-events-spinner");const e=new URLSearchParams(window.location.search);fetch(`/api/update-events/?auth=${e.get("auth")}`,{method:"POST"}).then((e=>{200!==e.status&&alert("Updating events failed!"),hideElementByID("update-events-spinner"),showElementByID("update-events-button")}))}function updateSponsors(){hideElementByID("update-sponsors-button"),showElementByID("update-sponsors-spinner");const e=new URLSearchParams(window.location.search);fetch(`/api/update-sponsors/?auth=${e.get("auth")}`,{method:"POST"}).then((e=>{200!==e.status&&alert("Updating sponsors failed!"),hideElementByID("update-sponsors-spinner"),showElementByID("update-sponsors-button")}))}